import sys, json, re, secrets, datetime, difflib, base64

# THE WORKSPACES OF A FILE SPACE (GH #902, R-27-7). A workspace is a set of
# pointers, never content: `ws` rows name it, `ws_files` rows appear only when
# a file is first touched (copy-on-write), and every new version is made by
# `./write` over `in_put` (`patch`, `merge3`, `create`) -- this cell only swings
# pointers: `ws_files.working`, `files.head`/`lock`, `commits.state`.
#
# The commit is two-phase with ONE commit point (README 2.7): a `commits` row
# `prepared` with its plan, a lock per file by compare-and-swap in file-id
# order, then `update commits set state='committed' where state='prepared'` --
# a single row, atomic on its own, because a store bundle is no transaction
# (`crates/meclaw-cells/src/store/cell.rs:46-56`). Readers resolve a locked
# file through that row, so a commit is visible all or nothing. Everything
# after the commit point (heads, `line` rows, `in_derive`) is idempotent and is
# finished by whoever meets the lock next: `in_recover` from `./write`, or the
# start of the next `ws_commit` over the same file.
#
# The cell runs `cold`: nothing lives in RAM between two messages. A request
# becomes a job parked in `pending` (key `op_id` = the job id, `cell` = 'ws');
# every store round trip rewrites the job and reads it back in the same bundle
# (the curator's pattern, `templates/curator/intake`), and a `put` answer of
# `./write` is parked next to it as its own row before the job reads on.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}

ME = "ws"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
# OR-FH-V2: a commit over a few files takes a fraction of a second; a
# prepared commit older than this is abandoned and anyone may abort it.
COMMIT_DEADLINE_MS = 60000
DIFF_MAX_LINES = 400
SCAN_LIMIT = 10000
ROW_LIMIT = 5000
MERGE_ROUNDS = 3
OPS = ("ws_open", "ws_status", "ws_diff", "ws_patch", "ws_merge", "ws_commit",
       "ws_discard", "ws_tree")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")
_MEM = {"seq": 0}


# ================================================================ PURE HALF
# Twin of `./read`'s `parse_addr`, word for word (GH #899 locks the twins).
def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def _patch_path(raw):
    """The path of a `---`/`+++` header: `/dev/null` is None, a git `a/`/`b/`
    prefix goes, a trailing tab-separated timestamp goes, the result is
    absolute."""
    p = raw.rstrip("\r\n").split("\t", 1)[0].strip()
    if p == "/dev/null":
        return None
    if p.startswith("a/") or p.startswith("b/"):
        p = p[2:]
    if not p:
        raise ValueError("a file header without a path")
    return p if p.startswith("/") else "/" + p


def split_patch(diff):
    """A unified multi-file diff cut into one entry per file, in input order:
    `{path, kind: modify|create|remove, hunks}`, a hunk being its `@@` line
    plus its body lines. The end of a hunk is its line counts, never a
    guess, so a removed line that reads `--- x` stays in its hunk. Raises
    ValueError on anything that is not a clean diff."""
    lines = str(diff or "").splitlines(keepends=True)
    files, cur, seen, i = [], None, set(), 0
    while i < len(lines):
        ln = lines[i]
        if ln.startswith("--- ") and i + 1 < len(lines) and lines[i + 1].startswith("+++ "):
            old, new = _patch_path(ln[4:]), _patch_path(lines[i + 1][4:])
            if old is None and new is None:
                raise ValueError("line %d: /dev/null on both sides" % (i + 1))
            if old is not None and new is not None and old != new:
                raise ValueError("line %d: a rename (%s -> %s) is not a patch" % (i + 1, old, new))
            kind = "create" if old is None else ("remove" if new is None else "modify")
            path = new if new is not None else old
            if path in seen:
                raise ValueError("line %d: %s appears twice" % (i + 1, path))
            seen.add(path)
            cur = {"path": path, "kind": kind, "hunks": []}
            files.append(cur)
            i += 2
            continue
        m = HUNK_RE.match(ln)
        if m:
            if cur is None:
                raise ValueError("line %d: a hunk before any file header" % (i + 1))
            old_n = int(m.group(2)) if m.group(2) is not None else 1
            new_n = int(m.group(4)) if m.group(4) is not None else 1
            if cur["kind"] == "create" and old_n:
                raise ValueError("line %d: a new file's hunk removes lines" % (i + 1))
            if cur["kind"] == "remove" and new_n:
                raise ValueError("line %d: a removed file's hunk adds lines" % (i + 1))
            body = [ln if ln.endswith("\n") else ln + "\n"]
            i += 1
            while i < len(lines) and (old_n > 0 or new_n > 0):
                b = lines[i]
                if b in ("\n", "\r\n"):
                    b = " " + b
                t = b[:1]
                if t == " ":
                    old_n -= 1
                    new_n -= 1
                elif t == "-":
                    old_n -= 1
                elif t == "+":
                    new_n -= 1
                elif t == "\\":
                    pass
                else:
                    raise ValueError("line %d: the hunk ends early" % (i + 1))
                if old_n < 0 or new_n < 0:
                    raise ValueError("line %d: the hunk is longer than its header" % (i + 1))
                body.append(b)
                i += 1
            if old_n or new_n:
                raise ValueError("the last hunk of %s is cut short" % cur["path"])
            while i < len(lines) and lines[i].startswith("\\"):
                body.append(lines[i])
                i += 1
            cur["hunks"].append("".join(body))
            continue
        if ln.strip() == "" or ln.startswith(("diff ", "index ", "new file mode",
                                               "deleted file mode", "old mode", "new mode",
                                               "similarity index")):
            i += 1
            continue
        raise ValueError("line %d: not part of a unified diff: %r" % (i + 1, ln[:60]))
    for f in files:
        if not f["hunks"] and f["kind"] != "remove":
            raise ValueError("%s has no hunk" % f["path"])
    return files


def file_diff(part):
    """One file's section of a diff, as `./write`'s `patch` reads it."""
    return "--- %s\n+++ %s\n%s" % (part["path"], part["path"], "".join(part["hunks"]))


def created_text(part):
    """The content of a file a diff creates: its `+` lines; a `\\ No newline`
    marker after the last one drops that line's end."""
    out = []
    for h in part["hunks"]:
        for b in h.splitlines(keepends=True)[1:]:
            if b.startswith("+"):
                out.append(b[1:])
            elif b.startswith("\\") and out:
                out[-1] = out[-1].rstrip("\r\n")
    return "".join(out)


def commit_plan(rows, heads):
    """The plan of a commit from the workspace's `ws_files` rows and the heads
    of those files (`{file: {head, lock, tomb}}`). One of:
    `{"conflict": [file]}` -- a workspace with a conflict does not commit;
    `{"tombstoned": [file]}` -- the main line removed a file this one edited;
    `{"base_moved": [file]}` -- this one removes a file the main line changed
    since (a removal does not merge: look again, then remove again);
    `{"behind": [file]}` -- merge the main line in first;
    `{"plan": [{file, from, to, kind}]}` sorted by file id, the lock order.
    A file born here and removed here falls out; a touched file whose working
    version is its base has nothing to commit."""
    conflict = sorted(str(r.get("file")) for r in rows if r.get("state") == "conflict")
    if conflict:
        return {"conflict": conflict}
    tomb, moved, behind, plan = [], [], [], []
    for r in sorted(rows, key=lambda r: str(r.get("file"))):
        f = str(r.get("file"))
        st = str(r.get("state") or "")
        h = heads.get(f) or {}
        head = str(h.get("head") or "")
        base = str(r.get("base") or "")
        working = str(r.get("working") or "")
        if st == "created":
            if working:
                plan.append({"file": f, "from": "", "to": working, "kind": "create"})
        elif st == "removed":
            if not base or h.get("tomb"):
                continue
            if head != base:
                moved.append(f)
            else:
                plan.append({"file": f, "from": head, "to": "", "kind": "remove"})
        else:
            if h.get("tomb"):
                tomb.append(f)
            elif head != base:
                behind.append(f)
            elif working and working != base:
                plan.append({"file": f, "from": base, "to": working, "kind": "modify"})
    if tomb:
        return {"tombstoned": tomb}
    if moved:
        return {"base_moved": moved}
    if behind:
        return {"behind": behind}
    return {"plan": plan}


def to_ms(value):
    """A stamp as ms since the epoch: an int, a digit string, or UTC ISO text.
    Unreadable is 0 -- a deadline nobody can read has passed."""
    if isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return int(value)
    s = str(value or "").strip()
    if re.fullmatch(r"\d+", s):
        return int(s)
    try:
        t = datetime.datetime.strptime(s.replace("+00:00", "Z"), FMT)
    except ValueError:
        try:
            t = datetime.datetime.strptime(s.rstrip("Z"), "%Y-%m-%dT%H:%M:%S")
        except ValueError:
            return 0
    return int(t.replace(tzinfo=datetime.timezone.utc).timestamp() * 1000)


def recover_action(commit_row, now_ms):
    """What the next visitor does with a commit it met through a lock:
    `finish` -- past the commit point, bring every head forward;
    `abort` -- prepared and past its deadline (strictly after it), or already
    aborted with locks left over: release them;
    `wait` -- prepared and still in time, or unknown: touch nothing."""
    st = str((commit_row or {}).get("state") or "")
    if st == "committed":
        return "finish"
    if st == "aborted":
        return "abort"
    if st == "prepared":
        return "abort" if int(now_ms) > to_ms(commit_row.get("deadline")) else "wait"
    return "wait"


def v12(version):
    return str(version or "")[:12]


def jload(value, default):
    if isinstance(value, (list, dict)):
        return value
    try:
        out = json.loads(str(value))
    except Exception:
        return default
    return out if isinstance(out, type(default)) else default


def content_of(version_row, block_rows):
    """The bytes of a version from its `blocks` list and the file's block
    rows; None when a block is missing."""
    by = {str(b.get("hash")): b for b in block_rows}
    out = b""
    for hsh in jload((version_row or {}).get("blocks"), []):
        b = by.get(str(hsh))
        if b is None:
            return None
        body = str(b.get("body") or "")
        out += base64.b64decode(body) if b.get("enc") == "b64" else body.encode("utf-8")
    return out


def as_text(raw):
    if raw is None:
        return None
    try:
        t = raw.decode("utf-8")
    except UnicodeDecodeError:
        return None
    return None if "\x00" in t else t


def unified(path, old, new, kind):
    """base -> working of one file, 3 lines of context; binary is one line."""
    a = "/dev/null" if kind == "create" else "a" + path
    b = "/dev/null" if kind == "remove" else "b" + path
    to, tn = as_text(old if old is not None else b""), as_text(new if new is not None else b"")
    if to is None or tn is None:
        return ["Binary files %s and %s differ" % (a, b)]
    return [ln.rstrip("\n") for ln in difflib.unified_diff(
        to.splitlines(keepends=True), tn.splitlines(keepends=True), a, b, n=3)]


def under_root(path, root):
    root = root or "/"
    if root == "/":
        return True
    r = root.rstrip("/")
    return path == r or path.startswith(r + "/")


# ================================================================ PLUMBING
def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def now_us():
    return int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000000)


def stamp_ms(ms):
    return datetime.datetime.fromtimestamp(ms / 1000.0, datetime.timezone.utc).strftime(FMT)


def now_ms():
    return now_us() // 1000


def emit(msgs):
    # OR-FJ.L.8: a body with none of `messages`/`system`/`attachments` is no
    # UBF body, and a debug colony dead-letters it without an answer
    # (`invalid_ubf_body`) -- measured in the gh908 colony lock on the
    # `in_check` of `write`. Every emission leaves with its slot.
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("file-space/ws: %s\n" % reason)
    emit([])


def sel(table, columns, where=None, order=None, limit=ROW_LIMIT):
    a = {"operation": "select", "table": table, "columns": columns, "limit": limit}
    if where:
        a["where"] = where
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, setv, where):
    return {"operation": "update", "table": table, "set": setv, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def lock_ops(C, plan):
    """The locks of commit `C`, one per file of `plan` in its (file-id) order.
    The CAS is W's main-line swing: `lock=''`, `head=from` AND `tomb=''` --
    W's `remove` sets only `tomb` and leaves `head`, so without `tomb=''` a
    remove between reading the heads and locking would let the commit land
    on a grave and answer `ok` (final review V I-1, OR-FH-95)."""
    return [("k:" + p["file"], upd("files", {"lock": C}, {"file": p["file"], "lock": "", "head": p["from"], "tomb": ""}))
            for p in plan]


def store(ops, phase):
    """One bundle to `./store`; the store edge lifts `phase` into
    `context.cur_phase` and `reply_cell` into `cur_origin`."""
    return {"header": {"route": "ws_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    """The answer of a store message by tool_call id (curator/intake)."""
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "",
                                       "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if not isinstance(r, dict):
                continue
            leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                 {"payload": None, "error_code": "", "rows_affected": 0})
            leg["error_code"] = str(r.get("error_code") or "")
            leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows_affected"] = int(hop.get("rows_affected") or 0)
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def affected(lg, cid):
    return int((lg.get(cid) or {}).get("rows_affected") or 0)


def failed(lg):
    return ["%s=%s" % (k, v["error_code"]) for k, v in lg.items() if v["error_code"]]


def seqs(n, floor=0):
    base = max(now_us(), _MEM["seq"] + 1, int(floor) + 1)
    _MEM["seq"] = base + n - 1
    return [base + i for i in range(n)]


# ================================================================ JOBS
def job_ops(job, first=False):
    row = {"op_id": job["id"], "cell": ME, "phase": "job", "body": json.dumps(job), "at": now()}
    head = ins("pending", row) if first else upd(
        "pending", {"body": row["body"], "at": row["at"]},
        {"op_id": job["id"], "cell": ME, "phase": "job"})
    return [("j-put", head), ("j-echo", sel("pending", ["phase", "body"],
                                            {"op_id": job["id"], "cell": ME}))]


def go(job, step, ops, extra=None, first=False):
    """Park the job at `step` and run `ops` in the same bundle."""
    job["step"] = step
    return [store(job_ops(job, first) + list(ops), "job|" + job["id"])] + list(extra or [])


def reply(job, payload):
    # `hop.ws` is the workspace NAME (OR-FH-81), in answers and on `in_put`
    # alike; `./write` resolves it to the id through the `ws` table.
    h = {"route": "answer", "op": job["op"], "op_id": job["op_id"], "caller": job["caller"]}
    if job.get("wsr"):
        h["ws"] = job["wsr"]["name"]
    body = {"ok": True, "op": job["op"], "op_id": job["op_id"], "messages": []}
    body.update(payload)
    return dict(body, header=h)


def refuse(job, code, message, **extra):
    h = {"route": "answer", "op": job.get("op", ""), "op_id": job.get("op_id", ""),
         "caller": job.get("caller", "")}
    if job.get("wsr"):
        h["ws"] = job["wsr"]["name"]
    err = {"code": code, "message": message}
    err.update(extra)
    return {"header": h, "ok": False, "op": job.get("op", ""), "op_id": job.get("op_id", ""),
            "error": err, "messages": []}


def close(job, ops, answer):
    """The job's last bundle (its own `pending` rows go) and its answer."""
    ops = list(ops) + [("j-drop", dele("pending", {"op_id": job["id"], "cell": ME}))]
    return [store(ops, "done|" + job["id"]), answer]


def fail(job, code, message, ops=(), **extra):
    return close(job, list(ops) + [("u%d" % i, op) for i, op in enumerate(job.get("undo") or [])],
                 refuse(job, code, message, **extra))


def put(job, op, file, args):
    """One `in_put` to `./write`; its answer comes back on `put` under the
    sub id `<job>.<n>` and is parked before the job reads on. The job row is
    written (`nop|`) in the same emission, ahead of the `in_put`: `./store`
    answers in arrival order, so the `put` answer -- even one `./write`
    sends without a store round of its own -- always finds the job at its
    `*_put` step (review V M-5)."""
    n = int(job.get("puts") or 0) + 1
    job["puts"] = n
    job["await"] = "put:%d" % n
    msg = {"header": {"route": "in_put", "op": op, "op_id": "%s.%d" % (job["id"], n),
                      "caller": ME, "ws": job["wsr"]["name"]},
           "op": op, "file": file, "args": args, "messages": []}
    return [store(job_ops(job), "nop|" + job["id"]), msg]


def at_base_seq(job, files_by_id, need):
    """Read ops for the main-line version at `base_seq` of the files in
    `need` whose head moved after it (a head that did not move IS that
    version). `line.seq <= base_seq`: a move in the same microsecond as the
    opening belongs to the basis."""
    bs = int(job["wsr"]["base_seq"])
    ops, known = [], {}
    for f in need:
        r = files_by_id.get(f) or {}
        if str(r.get("head") or "") and int(r.get("head_seq") or 0) <= bs:
            known[f] = str(r["head"])
        else:
            ops.append(("l:" + f, sel("line", ["version", "op", "seq"],
                                      {"file": f, "seq": {"lte": bs}}, [("seq", "desc")], 1)))
    return ops, known


def base_versions(lg, known):
    out = dict(known)
    for cid in lg:
        if cid.startswith("l:"):
            r = rows(lg, cid)
            if r and str(r[0].get("op") or "") != "remove":
                out[cid[2:]] = str(r[0].get("version") or "")
    return out


# ----------------------------------------------------------------- recovery
def rec_start(C):
    return [("r-c", sel("commits", ["commit", "ws", "state", "plan", "note", "deadline"],
                        {"commit": C}, None, 1))]


def in_derive(C, f, version):
    """`in_derive` for a head a commit moved: the full version, never `ws` at
    the hop (OR-FH-73), `notify`/`caller`/`op_id` always there (W's form,
    OR-FH-80); `op_id` is the commit."""
    return {"header": {"route": "in_derive", "notify": "", "caller": "", "op_id": C},
            "file": f, "version": version, "messages": []}


def rec_step(stage, C, lg):
    """One stage of the recovery of commit C: returns (ops, next stage or
    None, emissions, finished files). Every stage re-reads the commit row,
    so nothing but the stage name travels between trips.

    Step 4 per file is `line` row FIRST, head swing second (OR-FH-75): the
    `line` row of (file, C) is read, written only when missing (read before
    write), and the claim `update files set head=to, head_seq=<its seq>,
    lock='' where file=F and lock=C` follows in the same bundle, after it.
    A crash between the two leaves `lock=C` and the row -- the next visitor
    finds the row and only claims; a head never moves without its row
    (README 2.6), so no workspace opened in the gap reads the version
    before (`line.seq <= base_seq`). Of two visitors only one wins the
    claim; a loser keeps the `line` row it wrote (append-only, OR-FH-85):
    two rows of one (file, C) carry the same version, and `history` shows
    one row per commit. The
    workspace turns `committed` in the same bundle, ahead of the claims:
    once no lock is left, nobody would come back for it."""
    cr = rows(lg, "r-c")
    if not cr:
        return [], None, [], []
    row = cr[0]
    plan = jload(row.get("plan"), [])
    files = sorted(str(p.get("file")) for p in plan)
    if not files:
        return [], None, [], []
    act = recover_action(row, now_ms())
    if stage == "r1":
        if act == "finish":
            ops = rec_start(C) + [("r-f", sel("files", ["file", "lock", "head_seq"],
                                              {"file": {"in": files}}, None, len(files)))]
            for p in plan:
                f = str(p.get("file"))
                if p.get("to"):
                    ops.append(("r-v:" + f, sel("versions", ["version", "bytes", "lines"],
                                                {"file": f, "version": p["to"]}, None, 1)))
                ops.append(("r-lx:" + f, sel("line", ["seq"], {"file": f, "commit": C},
                                             [("seq", "asc")], 1)))
            return ops, "r2", [], []
        if act == "abort":
            ops = rec_start(C)
            if row.get("state") == "prepared":
                ops.insert(0, ("r-ab", upd("commits", {"state": "aborted"},
                                           {"commit": C, "state": "prepared"})))
            return ops, "r2a", [], []
        return [], None, [], []
    if stage == "r2a":
        if act == "finish":
            return rec_step("r1", C, lg)
        if row.get("state") != "aborted":
            return [], None, [], []
        return ([("r-un:" + f, upd("files", {"lock": ""}, {"file": f, "lock": C}))
                 for f in files], None, [], [])
    if stage == "r2":
        if act != "finish":
            return [], None, [], []
        frows = {str(r.get("file")): r for r in rows(lg, "r-f")}
        ops = rec_start(C)
        wsid = str(row.get("ws") or "")
        if wsid:
            ops.append(("r-ws", upd("ws", {"state": "committed", "closed_at": now(), "commit": C},
                                    {"ws": wsid, "state": "open"})))
        claim = []
        for p in sorted(plan, key=lambda p: str(p.get("file"))):
            f = str(p["file"])
            fr = frows.get(f)
            if not fr or str(fr.get("lock") or "") != C:
                continue
            rm = p.get("kind") == "remove"
            have = rows(lg, "r-lx:" + f)
            if have:
                seq = int(have[0].get("seq") or 0)
            else:
                seq = seqs(1, fr.get("head_seq") or 0)[0]
                ops.append(("r-l:%s|%d" % (f, seq), ins("line", {
                    "file": f, "seq": seq, "version": p["from"] if rm else p["to"],
                    "prev": p.get("from") or "", "op": "remove" if rm else "commit",
                    "note": str(row.get("note") or ""), "ws": wsid, "commit": C, "at": now()})))
            if rm:
                setv = {"tomb": now(), "lock": "", "head_seq": seq}
            else:
                vr = rows(lg, "r-v:" + f)
                setv = {"head": p["to"], "head_seq": seq, "lock": ""}
                if vr:
                    setv["bytes"] = vr[0].get("bytes")
                    setv["lines"] = vr[0].get("lines")
            # The claim IS the step: of two visitors only one sees lock=C.
            ops.append(("r-cl:" + f, upd("files", setv, {"file": f, "lock": C})))
            claim.append(f)
        if not claim:
            return [op for op in ops if op[0] == "r-ws"], None, [], []
        return ops, "r3", [], []
    if stage == "r3":
        ops, out, done = [], [], []
        for p in sorted(plan, key=lambda p: str(p.get("file"))):
            f = str(p["file"])
            if affected(lg, "r-cl:" + f) != 1:
                continue
            done.append(p)
            if p.get("kind") != "remove":
                out.append(in_derive(C, f, p["to"]))
        # A visitor that lost the claim leaves its `line` row standing (OR-FH-85): the main
        # line is append-only, and the twin row carries the same version under the same
        # commit, so `history` shows one row per commit and `seq <= base_seq` is unmoved.
        return ops, None, out, done
    return [], None, [], []


# ================================================================ LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "in_recover":
    C = str(d.get("commit") or "")
    if not C:
        park("in_recover without a commit -- dropped")
    emit([store(rec_start(C), "rec:r1|" + C)])

if lane == "put":
    sub = str(hop.get("op_id") or d.get("op_id") or "")
    jid, _, n = sub.rpartition(".")
    if not jid or not n.isdigit():
        park("a put answer without a job id (%r) -- dropped" % sub)
    answer = {k: v for k, v in d.items() if k not in ("header", "messages")}
    emit([store([("p-put", ins("pending", {"op_id": jid, "cell": ME, "phase": "put:" + n,
                                           "body": json.dumps(answer), "at": now()})),
                 ("j-echo", sel("pending", ["phase", "body"], {"op_id": jid, "cell": ME}))],
                "job|" + jid)])

if lane == "in_ws":
    op = str(d.get("op") or hop.get("op") or "")
    args = d.get("args") if isinstance(d.get("args"), dict) else {}
    job = {"id": "ws-job-" + secrets.token_hex(8), "op": op,
           "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
           "args": args, "ref": str(hop.get("ws") or args.get("ws") or "")}
    if not job["op_id"]:
        emit([refuse(job, "bad_request", "op_id is required")])
    if op not in OPS:
        emit([refuse(job, "unknown_op", "no workspace op %r" % op)])
    if op == "ws_open":
        name = str(args.get("name") or "")
        root = str(args.get("root") or "/")
        if not NAME_RE.match(name):
            emit([refuse(job, "bad_request", "name must match [A-Za-z0-9._-]{1,64}")])
        if not root.startswith("/"):
            emit([refuse(job, "bad_request", "root must be an absolute path prefix")])
        emit(go(job, "open", [("w-n", sel("ws", ["ws"], {"name": name, "state": "open"},
                                             None, 1))], first=True))
    if not job["ref"]:
        emit([refuse(job, "ws_unknown", "name the workspace in hop.ws or args.ws")])
    emit(go(job, "resolve", [
        ("w-id", sel("ws", ["ws", "name", "root", "base_seq", "state"], {"ws": job["ref"]},
                     None, 1)),
        ("w-n", sel("ws", ["ws", "name", "root", "base_seq", "state"], {"name": job["ref"]},
                    [("opened_at", "desc")], 20))], first=True))

if lane:
    park("unknown lane %r -- dropped" % lane)

# ================================================================ STORE ANSWERS
kind, _, key = phase.partition("|")
if not key:
    park("a message with neither a lane nor a store phase -- dropped")
lg = legs(d)
bad = failed(lg)
if kind in ("done", "nop"):
    if bad:
        sys.stderr.write("file-space/ws: store legs failed in %s: %s\n" % (phase, ",".join(bad)))
    emit([])

if kind.startswith("rec:"):
    if bad:
        park("recovery of %s: store legs failed: %s" % (key, ",".join(bad)))
    ops, nxt, out, _ = rec_step(kind[4:], key, lg)
    msgs = list(out)
    if ops:
        msgs.insert(0, store(ops, ("rec:%s|%s" % (nxt, key)) if nxt else "done|" + key))
    emit(msgs)

if kind != "job":
    park("store answer in unknown phase %r -- dropped" % phase)

job, puts = None, {}
for r in rows(lg, "j-echo"):
    ph = str(r.get("phase") or "")
    if ph == "job":
        job = jload(r.get("body"), {})
    elif ph.startswith("put:"):
        puts[ph] = jload(r.get("body"), {})
if not job:
    park("job %s came back without its row (%s) -- dropped" % (key, ",".join(bad)))
if bad:
    emit(fail(job, "store_error", "store legs failed: %s" % ",".join(bad)))
step = job.get("step", "")
wsr = job.get("wsr") or {}


def got_put():
    """The awaited `put` answer, or None while it has not arrived."""
    a = job.get("await") or ""
    return puts.get(a) if a else None


def ws_files_ops():
    # ws_files is enumerated by workspace, never across files of other
    # workspaces: the workspace IS the scope of these rows (OR-FH.V.1).
    return [("wf", sel("ws_files", ["file", "base", "working", "state"], {"ws": wsr["ws"]}))]


def files_ops(ids, cid="f"):
    ids = sorted(set(ids))
    if not ids:
        return []
    return [(cid, sel("files", ["file", "path", "kind", "head", "head_seq", "lock", "tomb"],
                      {"file": {"in": ids}}, None, len(ids)))]


def by_file(lst):
    return {str(r.get("file")): r for r in lst}


def patch_loop(job):
    """The order of `ws_patch`: every modify made (`in_put patch`), then all
    of them swung at once, then the creates made, then the created rows and
    the removes written. Nothing swings before every modify was made."""
    plan = job["plan"]
    order = job["mods"] + job["crs"]
    pos = job["pos"]
    if pos < len(job["mods"]) or (job.get("swung") and pos < len(order)):
        e = plan[order[pos]]
        job["step"] = "patch_put"
        if e["kind"] == "modify":
            return put(job, "patch", e["file"], {"base": e["old"], "diff": e["diff"]})
        return put(job, "create", "", {"path": e["path"], "text": e["text"]})
    if not job.get("swung"):
        ops = []
        for k in job["mods"]:
            e = plan[k]
            f = e["file"]
            if e["row"]:
                ops.append(("s:" + f, upd("ws_files", {"working": e["new"], "at": now()},
                                          {"ws": wsr["ws"], "file": f, "working": e["old"]})))
            else:
                ops.append(("s:" + f, ins("ws_files", {"ws": wsr["ws"], "file": f,
                                                       "base": e["base"], "working": e["new"],
                                                       "state": "touched", "at": now()})))
        return go(job, "patch_swung", ops)
    # The creates need no row of their own here: `./write`'s `in_put create`
    # with `ws` writes the `ws_files(created)` row itself (OR-FH-78). A second
    # row made every commit of a born file plan it twice, and the second lock
    # compare-and-swap then missed -- `busy` (contract review V C-1).
    ops = []
    for e in plan:
        if e["kind"] != "remove":
            continue
        f = e["file"]
        if e["row"]:
            ops.append(("s:" + f, upd("ws_files", {"state": "removed", "working": "",
                                                   "at": now()},
                                      {"ws": wsr["ws"], "file": f, "working": e["old"]})))
            if not e["base"]:
                # born in this workspace: it falls out of the plan, its grave
                # frees the path
                ops.append(("t:" + f, upd("files", {"tomb": now()},
                                          {"file": f, "head": "", "tomb": ""})))
        else:
            ops.append(("s:" + f, ins("ws_files", {"ws": wsr["ws"], "file": f, "base": e["base"],
                                                   "working": "", "state": "removed",
                                                   "at": now()})))
    return go(job, "patch_done", ops)


# ------------------------------------------------------------- open/resolve
if step == "open":
    if rows(lg, "w-n"):
        emit(fail(job, "ws_exists", "an open workspace is already named %r" % job["args"]["name"]))
    wid = "ws-" + secrets.token_hex(6)
    bs = now_us()
    root = str(job["args"].get("root") or "/")
    emit(close(job, [("w-ins", ins("ws", {"ws": wid, "name": job["args"]["name"], "root": root,
                                          "base_seq": bs, "state": "open", "opened_at": now(),
                                          "closed_at": "", "commit": ""}))],
               reply(dict(job, wsr={"ws": wid, "name": job["args"]["name"]}), {"ws": wid, "name": job["args"]["name"],
                                                "root": root, "base_seq": bs})))

if step == "resolve":
    cand = rows(lg, "w-id") or rows(lg, "w-n")
    live = [r for r in cand if r.get("state") == "open"]
    if not cand:
        emit(fail(job, "ws_unknown", "no workspace %r" % job["ref"]))
    if not live:
        emit(fail(job, "ws_closed", "workspace %r is %s" % (job["ref"], cand[0].get("state"))))
    w = live[0]
    job["wsr"] = {"ws": str(w["ws"]), "name": str(w.get("name") or ""),
                "root": str(w.get("root") or "/"), "base_seq": int(w.get("base_seq") or 0)}
    wsr = job["wsr"]
    op = job["op"]
    if op == "ws_tree":
        emit(go(job, "tree1", ws_files_ops() + [
            ("all", sel("files", ["file", "path", "kind", "head", "head_seq", "tomb"],
                        None, [("path", "asc")], SCAN_LIMIT))]))
    if op == "ws_patch":
        try:
            parts = split_patch(job["args"].get("diff"))
        except ValueError as e:
            emit(fail(job, "patch_invalid", str(e)))
        if not parts:
            emit(fail(job, "patch_invalid", "the diff names no file"))
        out = [p["path"] for p in parts if not under_root(p["path"], wsr["root"])]
        if out:
            emit(fail(job, "outside_root", "outside the workspace root %s" % wsr["root"],
                      paths=out))
        job["parts"] = parts
        paths = sorted(set(p["path"] for p in parts))
        emit(go(job, "patch1", ws_files_ops() + [
            ("fp", sel("files", ["file", "path", "kind", "head", "head_seq", "tomb"],
                       {"path": {"in": paths}, "tomb": ""}, None, len(paths) * 4))]))
    emit(go(job, {"ws_status": "status1", "ws_diff": "diff1", "ws_merge": "merge1",
                  "ws_commit": "commit1", "ws_discard": "discard1"}[op], ws_files_ops()))

# ------------------------------------------------------------------ status
if step == "status1":
    wf = rows(lg, "wf")
    if not wf:
        emit(close(job, [], reply(job, {"files": []})))
    job["wf"] = wf
    emit(go(job, "status2", files_ops([r["file"] for r in wf])))

if step == "status2":
    fr = by_file(rows(lg, "f"))
    out = []
    for r in sorted(job["wf"], key=lambda r: str(r.get("file"))):
        f = str(r["file"])
        x = fr.get(f) or {}
        e = {"file": f, "path": x.get("path", ""), "state": r.get("state"),
             "base": v12(r.get("base")), "working": v12(r.get("working")),
             "behind": bool(r.get("base")) and str(x.get("head") or "") != str(r.get("base"))}
        out.append({k: v for k, v in e.items() if v != "" or k in ("base", "working")})
    emit(close(job, [], reply(job, {"files": out})))

# -------------------------------------------------------------------- diff
if step == "diff1":
    wf = rows(lg, "wf")
    if not wf:
        emit(close(job, [], reply(job, {"diff": "", "files": []})))
    job["wf"] = wf
    ops = files_ops([r["file"] for r in wf])
    for r in wf:
        vs = [v for v in (r.get("base"), r.get("working")) if v]
        if vs:
            ops.append(("v:" + r["file"], sel("versions", ["version", "blocks"],
                                               {"file": r["file"], "version": {"in": vs}},
                                               None, 2)))
    emit(go(job, "diff2", ops))

if step == "diff2":
    job["paths"] = {f: str(x.get("path") or "") for f, x in by_file(rows(lg, "f")).items()}
    vers, ops = {}, []
    for r in job["wf"]:
        f = r["file"]
        vr = rows(lg, "v:" + f)
        vers[f] = vr
        hs = sorted(set(h for v in vr for h in jload(v.get("blocks"), [])))
        if hs:
            ops.append(("b:" + f, sel("blocks", ["hash", "enc", "body"],
                                      {"file": f, "hash": {"in": hs}}, None, len(hs))))
    job["vers"] = vers
    emit(go(job, "diff3", ops))

if step == "diff3":
    text, files, more = [], [], False
    for r in sorted(job["wf"], key=lambda r: str(r.get("file"))):
        f = r["file"]
        st = r.get("state")
        if st == "created" and not r.get("working"):
            continue
        kind = "create" if st == "created" else ("remove" if st == "removed" else "modify")
        vr = {str(v.get("version")): v for v in job["vers"].get(f, [])}
        br = rows(lg, "b:" + f)
        old = content_of(vr.get(str(r.get("base"))), br) if kind != "create" else b""
        new = content_of(vr.get(str(r.get("working"))), br) if kind != "remove" else b""
        chunk = unified(job["paths"].get(f, f), old, new, kind)
        if not chunk:
            continue
        files.append({"file": f, "path": job["paths"].get(f, ""), "state": st})
        room = DIFF_MAX_LINES - len(text)
        if len(chunk) > room:
            text.extend(chunk[:max(room, 0)])
            more = True
            break
        text.extend(chunk)
    payload = {"diff": "\n".join(text) + ("\n" if text else ""), "files": files}
    if more:
        payload["more"] = True
    emit(close(job, [], reply(job, payload)))

# -------------------------------------------------------------------- tree
if step == "tree1":
    wf = by_file(rows(lg, "wf"))
    alls = [r for r in rows(lg, "all") if under_root(str(r.get("path") or ""), wsr["root"])]
    job["tree"] = [{"file": r["file"], "path": r.get("path", ""), "kind": r.get("kind", "")}
                   for r in alls]
    job["tw"] = {f: {"state": r.get("state"), "working": r.get("working")} for f, r in wf.items()}
    need = [r["file"] for r in alls if r["file"] not in wf and not (
        r.get("tomb") and int(r.get("head_seq") or 0) <= wsr["base_seq"])]
    ops, known = at_base_seq(job, by_file(alls), need)
    job["known"] = known
    emit(go(job, "tree2", ops))

if step == "tree2":
    at = base_versions(lg, job["known"])
    out = []
    for t in job["tree"]:
        f = t["file"]
        w = job["tw"].get(f)
        if w:
            if w["state"] == "removed" or not w.get("working"):
                continue
            v = w["working"]
        else:
            v = at.get(f, "")
            if not v:
                continue
        out.append(dict(t, version=v12(v)))
    # `name` and `root` for the projection (GH #905): it lays the tree out
    # relative to the root, in a directory named after the workspace, and a
    # caller may have named it by id (OR-FJ.J.1)
    emit(close(job, [], reply(job, {"files": out, "name": wsr["name"], "root": wsr["root"]})))

# ----------------------------------------------------------------- discard
if step == "discard1":
    job["born"] = [r["file"] for r in rows(lg, "wf")
                   if r.get("state") == "created" or (r.get("state") == "removed"
                                                      and not r.get("base"))]
    emit(go(job, "discard2", [("w-cas", upd("ws", {"state": "discarded", "closed_at": now()},
                                            {"ws": wsr["ws"], "state": "open"}))]))

if step == "discard2":
    if affected(lg, "w-cas") != 1:
        emit(fail(job, "ws_closed", "workspace %r closed meanwhile" % wsr["name"]))
    # A file born here has no main line (`head=''`); its grave frees the path.
    ops = [("t:" + f, upd("files", {"tomb": now()}, {"file": f, "head": "", "tomb": ""}))
           for f in job["born"]]
    emit(close(job, ops, reply(job, {"ws": wsr["ws"], "name": wsr["name"], "state": "discarded"})))

# ------------------------------------------------------------------- patch
if step == "patch1":
    wf = by_file(rows(lg, "wf"))
    byp = {}
    for r in rows(lg, "fp"):
        byp.setdefault(str(r.get("path")), []).append(r)
    job["wf"] = wf
    plan, need, frows = [], [], {}
    for p in job["parts"]:
        cands = byp.get(p["path"]) or []
        # A file born in ANOTHER workspace (`head=''`, no ws_files row here)
        # is not part of this workspace's view.
        mine = [r for r in cands if str(r.get("head") or "") or r["file"] in wf]
        if p["kind"] == "create":
            if cands:
                emit(fail(job, "path_taken", "%s exists" % p["path"], path=p["path"]))
            plan.append({"path": p["path"], "kind": "create", "text": created_text(p)})
            continue
        if not mine:
            emit(fail(job, "patch_failed", "%s: no such file" % p["path"], path=p["path"]))
        r = mine[0]
        f = r["file"]
        frows[f] = r
        w = wf.get(f)
        if w and w.get("state") == "removed":
            emit(fail(job, "patch_failed", "%s is removed in this workspace" % p["path"],
                      path=p["path"]))
        e = {"path": p["path"], "kind": p["kind"], "file": f, "diff": file_diff(p),
             "row": bool(w), "old": str((w or {}).get("working") or ""),
             "base": str((w or {}).get("base") or ""),
             "was": str((w or {}).get("state") or "")}
        if not w:
            need.append(f)
        plan.append(e)
    job["plan"] = plan
    ops, known = at_base_seq(job, frows, need)
    job["known"] = known
    emit(go(job, "patch2", ops))

if step == "patch2":
    at = base_versions(lg, job["known"])
    for e in job["plan"]:
        if e["kind"] != "create" and not e["row"]:
            e["base"] = at.get(e["file"], "")
            e["old"] = e["base"]
            if not e["old"]:
                emit(fail(job, "patch_failed", "%s did not exist at the workspace's basis"
                          % e["path"], path=e["path"]))
    job["mods"] = [k for k, e in enumerate(job["plan"]) if e["kind"] == "modify"]
    job["crs"] = [k for k, e in enumerate(job["plan"]) if e["kind"] == "create"]
    job["pos"] = 0
    job["undo"] = []
    emit(patch_loop(job))

if step == "patch_put":
    a = got_put()
    if a is None:
        park("job %s: woke without its put answer" % job["id"])
    order = job["mods"] + job["crs"]
    e = job["plan"][order[job["pos"]]]
    if not a.get("ok"):
        err = a.get("error") or {}
        emit(fail(job, "patch_failed", "%s: %s" % (e["path"], err.get("message", "")),
                  path=e["path"], detail=err))
    e["new"] = str(a.get("version") or "")
    if e["kind"] == "create":
        e["file"] = str(a.get("file") or "")
        # Born by this job (its `ws_files(created)` row is `./write`'s,
        # OR-FH-78): should a later step fail, that row turns `removed` and
        # the grave frees the path again.
        job["undo"] += [upd("ws_files", {"state": "removed", "at": now()},
                            {"ws": wsr["ws"], "file": e["file"], "state": "created"}),
                        upd("files", {"tomb": now()}, {"file": e["file"], "head": "", "tomb": ""})]
    job["pos"] += 1
    emit(patch_loop(job))

if step == "patch_swung":
    plan = job["plan"]
    mods = [plan[k] for k in job["mods"]]
    lost = [e for e in mods if e["row"] and affected(lg, "s:" + e["file"]) != 1]
    for e in mods:
        if e in lost:
            continue
        job["undo"].append(
            upd("ws_files", {"working": e["old"]}, {"ws": wsr["ws"], "file": e["file"],
                                                    "working": e["new"]}) if e["row"]
            else dele("ws_files", {"ws": wsr["ws"], "file": e["file"], "working": e["new"]}))
    if lost:
        emit(fail(job, "busy", "%s moved in this workspace meanwhile" % lost[0]["path"],
                  path=lost[0]["path"]))
    job["swung"] = True
    emit(patch_loop(job))

if step == "patch_done":
    plan = job["plan"]
    rms = [e for e in plan if e["kind"] == "remove"]
    lost = [e for e in rms if e["row"] and affected(lg, "s:" + e["file"]) != 1]
    if lost:
        undo = list(job["undo"])
        for e in rms:
            if e in lost:
                continue
            undo.append(upd("ws_files", {"state": e["was"], "working": e["old"]},
                            {"ws": wsr["ws"], "file": e["file"], "working": ""}) if e["row"]
                        else dele("ws_files", {"ws": wsr["ws"], "file": e["file"],
                                               "state": "removed"}))
        # the files this job gave birth to stay, as `removed`, their paths
        # free: their undo entries were queued at birth (step `patch_put`)
        job["undo"] = undo
        emit(fail(job, "busy", "%s moved in this workspace meanwhile" % lost[0]["path"],
                  path=lost[0]["path"]))
    out = [{"file": e["file"], "path": e["path"], "kind": e["kind"],
            "version": v12(e.get("new", ""))} for e in plan]
    job["undo"] = []
    emit(close(job, [], reply(job, {"files": [{k: v for k, v in x.items() if v != ""}
                                              for x in out]})))

# ------------------------------------------------------------- merge/commit
def merge_start(job, wf, fr):
    """The files the main line moved under: `in_put merge3` for each, one by
    one; None when nothing moved."""
    todo = []
    for r in sorted(wf, key=lambda r: str(r.get("file"))):
        f = str(r["file"])
        head = str((fr.get(f) or {}).get("head") or "")
        if r.get("state") in ("touched", "conflict") and head and head != str(r.get("base")):
            todo.append({"file": f, "path": (fr.get(f) or {}).get("path", ""),
                         "base": str(r.get("base") or ""), "ours": str(r.get("working") or ""),
                         "theirs": head, "was": r.get("state")})
    job["mtodo"] = todo
    job["mi"] = 0
    return todo


def merge_next(job):
    todo = job["mtodo"]
    i = job["mi"]
    if i < len(todo):
        t = todo[i]
        job["step"] = "merge_put"
        return put(job, "merge3", t["file"], {"base": t["base"], "ours": t["ours"],
                                              "theirs": t["theirs"]})
    ops = []
    for t in todo:
        st = "conflict" if (t.get("conflicts") or t["was"] == "conflict") else "touched"
        ops.append(("m:" + t["file"], upd("ws_files", {"working": t["new"], "base": t["theirs"],
                                                       "state": st, "at": now()},
                                          {"ws": wsr["ws"], "file": t["file"],
                                           "working": t["ours"]})))
    return go(job, "merge_swung", ops)


if step == "merge1" or step == "commit1":
    again = rows(lg, "w-st")
    if again and again[0].get("state") != "open":
        emit(fail(job, "ws_closed", "workspace %r is %s" % (wsr["name"], again[0].get("state"))))
    wf = rows(lg, "wf")
    job["wf"] = wf
    if not wf:
        if step == "merge1":
            emit(close(job, [("w-bs", upd("ws", {"base_seq": now_us()},
                                          {"ws": wsr["ws"], "state": "open"}))],
                       reply(job, {"merged": [], "conflicts": []})))
        emit(close(job, [("w-c", upd("ws", {"state": "committed", "closed_at": now(),
                                            "commit": ""}, {"ws": wsr["ws"], "state": "open"}))],
                   reply(job, {"files": []})))
    if step == "commit1":
        cf = [r for r in wf if r.get("state") == "conflict"]
        if cf:
            emit(fail(job, "conflict", "resolve the conflicts first",
                      files=sorted(str(r["file"]) for r in cf)))
    emit(go(job, step[:-1] + "2", files_ops([r["file"] for r in wf])))

if step == "merge2":
    fr = by_file(rows(lg, "f"))
    if not merge_start(job, job["wf"], fr):
        emit(close(job, [("w-bs", upd("ws", {"base_seq": now_us()},
                                      {"ws": wsr["ws"], "state": "open"}))],
                   reply(job, {"merged": [], "conflicts": []})))
    emit(merge_next(job))

if step == "merge_put":
    a = got_put()
    if a is None:
        park("job %s: woke without its put answer" % job["id"])
    t = job["mtodo"][job["mi"]]
    if not a.get("ok"):
        err = a.get("error") or {}
        emit(fail(job, "merge_failed", "%s: %s" % (t["path"], err.get("message", "")),
                  file=t["file"], detail=err))
    t["new"] = str(a.get("version") or "")
    t["conflicts"] = a.get("conflicts") or a.get("lines") or []
    job["mi"] += 1
    emit(merge_next(job))

if step == "merge_swung":
    lost = [t for t in job["mtodo"] if affected(lg, "m:" + t["file"]) != 1]
    if lost:
        # base_seq stays: a merge that did not land on every file did not happen
        emit(fail(job, "busy", "%s moved in this workspace meanwhile" % lost[0]["path"],
                  file=lost[0]["file"]))
    merged = [{"file": t["file"], "path": t["path"], "version": v12(t["new"])}
              for t in job["mtodo"] if not t.get("conflicts")]
    conf = [{"file": t["file"], "path": t["path"], "lines": t["conflicts"]}
            for t in job["mtodo"] if t.get("conflicts")]
    bs = [("w-bs", upd("ws", {"base_seq": now_us()}, {"ws": wsr["ws"], "state": "open"}))]
    if job["op"] == "ws_merge":
        emit(close(job, bs, reply(job, {"merged": merged, "conflicts": conf})))
    if conf:
        emit(fail(job, "conflict", "the main line moved under these lines", ops=bs,
                  files=conf))
    job["rounds"] = int(job.get("rounds") or 0) + 1
    if job["rounds"] >= MERGE_ROUNDS:
        emit(fail(job, "busy", "the main line keeps moving", ops=bs))
    emit(go(job, "commit1", bs + ws_files_ops()))

if step == "commit2":
    fr = by_file(rows(lg, "f"))
    locks = sorted(set(str(r.get("lock") or "") for r in fr.values()) - {""})
    if locks and not job.get("recovered"):
        # Recovery first, for exactly the commits that lock this job's files.
        job["recovered"] = True
        job["rq"] = locks
        emit(go(job, "rec", rec_start(locks[0])))
    heads = {f: {"head": r.get("head"), "lock": r.get("lock"), "tomb": r.get("tomb")}
             for f, r in fr.items()}
    cp = commit_plan(job["wf"], heads)
    if "tombstoned" in cp:
        emit(fail(job, "tombstoned", "the main line removed a file this workspace edits",
                  files=cp["tombstoned"]))
    if "base_moved" in cp:
        emit(fail(job, "base_moved", "the main line changed a file this workspace removes",
                  files=cp["base_moved"]))
    if "behind" in cp:
        merge_start(job, job["wf"], fr)
        emit(merge_next(job))
    plan = cp["plan"]
    if not plan:
        emit(close(job, [("w-c", upd("ws", {"state": "committed", "closed_at": now(),
                                            "commit": ""}, {"ws": wsr["ws"], "state": "open"}))],
                   reply(job, {"files": []})))
    held = [p["file"] for p in plan if str((fr.get(p["file"]) or {}).get("lock") or "")]
    if held:
        # still locked after recovery: a commit in time holds it -- no wait
        emit(fail(job, "busy", "%s is locked by a commit in progress" % held[0], files=held))
    C = "c-" + secrets.token_hex(6)
    job["C"] = C
    job["plan"] = plan
    ops = [("c-ins", ins("commits", {"commit": C, "ws": wsr["ws"], "state": "prepared",
                                     "plan": json.dumps(plan),
                                     "note": str(job["args"].get("note") or ""), "at": now(),
                                     "deadline": stamp_ms(now_ms() + COMMIT_DEADLINE_MS)}))]
    # Locks in file-id order: two commits over the same files lock in the
    # same order, the loser releases and answers `busy` -- no wait, no cycle.
    ops += lock_ops(C, plan)
    emit(go(job, "commit_locked", ops))

if step == "rec":
    ops, nxt, out, _ = rec_step(job.get("rst") or "r1", job["rq"][0], lg)
    if nxt:
        job["rst"] = nxt
        emit(go(job, "rec", ops, out))
    job["rq"] = job["rq"][1:]
    job["rst"] = "r1"
    if job["rq"]:
        emit(go(job, "rec", ops + rec_start(job["rq"][0]), out))
    # The recovery may have finished THIS workspace's own earlier commit (a
    # crash after its commit point): read its state again (review V M-2).
    emit(go(job, "commit1", ops + ws_files_ops() + [
        ("w-st", sel("ws", ["state"], {"ws": wsr["ws"]}, None, 1))], out))

if step == "commit_locked":
    C = job["C"]
    lost = [p for p in job["plan"] if affected(lg, "k:" + p["file"]) != 1]
    unlock = [("un:" + p["file"], upd("files", {"lock": ""}, {"file": p["file"], "lock": C}))
              for p in job["plan"]]
    if lost or affected(lg, "c-ins") != 1:
        # Only this job ever sets `committed` on C, so releasing in the same
        # bundle as the abort cannot undo a commit.
        emit(fail(job, "busy", "a file is locked or moved: %s" % (lost[0]["file"] if lost else C),
                  ops=[("c-ab", upd("commits", {"state": "aborted"},
                                    {"commit": C, "state": "prepared"}))] + unlock))
    # THE COMMIT POINT: one row, one update, nothing else in this bundle.
    emit(go(job, "commit_point", [("c-pt", upd("commits", {"state": "committed"},
                                              {"commit": C, "state": "prepared"}))]))

if step == "commit_point":
    C = job["C"]
    if affected(lg, "c-pt") != 1:
        # A visitor aborted C after its deadline; its locks are ours to drop.
        emit(fail(job, "busy", "the commit ran past its deadline and was aborted",
                  ops=[("un:" + p["file"], upd("files", {"lock": ""},
                                               {"file": p["file"], "lock": C}))
                       for p in job["plan"]]))
    job["rst"] = "r1"
    emit(go(job, "finish", rec_start(C)))

if step == "finish":
    C = job["C"]
    stage = job.get("rst") or "r1"
    ops, nxt, out, done = rec_step(stage, C, lg)
    if ops and nxt:
        job["rst"] = nxt
        emit(go(job, "finish", ops, out))
    files = [{"file": p["file"], "version": v12(p["to"])} if p["kind"] != "remove"
             else {"file": p["file"], "removed": True} for p in job["plan"]]
    emit(close(job, list(ops), reply(job, {"commit": C, "files": files})) + out)

park("job %s in unknown step %r -- dropped" % (job.get("id"), step))
